=================== Makefile
     1	# term-project (Dark Sky Monitor) — CS 370
     2	# Every target does what its name says. CLAUDE.md treats a lying target as a bug.
     3	
     4	CC := gcc
     5	
     6	# _POSIX_C_SOURCE: with -std=c17, the Pi's glibc hides fsync, ftruncate, pread
     7	# and clock_gettime unless this is defined, and -Werror then fails the build.
     8	# macOS shows them anyway, so leaving this out would only break on the Pi.
     9	CFLAGS := -std=c17 -Wall -Wextra -Werror -g -O1 -Isrc -Itests \
    10	          -D_POSIX_C_SOURCE=200809L
    11	SANFLAGS := -fsanitize=address,undefined -fno-omit-frame-pointer
    12	
    13	# Library code (no main). Each step adds its files here.
    14	SRC  := src/common/crc32.c src/common/record.c src/store/store.c
    15	TSRC := tests/test_main.c tests/test_crc32.c tests/test_record.c tests/test_store.c
    16	HDR  := tests/check.h tests/suites.h src/common/crc32.h src/common/record.h \
    17	        src/store/store.h
    18	
    19	TESTBIN := build/test_all
    20	
    21	## all: build the test binary
    22	all: $(TESTBIN)
    23	
    24	$(TESTBIN): $(SRC) $(TSRC) $(HDR)
    25		@mkdir -p build
    26		$(CC) $(CFLAGS) $(SRC) $(TSRC) -o $@
    27	
    28	## test: run every test suite
    29	test: $(TESTBIN)
    30		./$(TESTBIN)
    31	
    32	## asan: rebuild with AddressSanitizer + UBSan and run the tests
    33	asan: CFLAGS += $(SANFLAGS)
    34	asan: clean test
    35	
    36	## memcheck: run the tests under valgrind (Linux/Pi only, not on macOS)
    37	memcheck: all
    38		@if ! command -v valgrind >/dev/null 2>&1; then \
    39		    echo "make memcheck: valgrind not installed here (expected on macOS - run this on the Pi)."; \
    40		  else \
    41		    valgrind --leak-check=full --show-leak-kinds=all --error-exitcode=1 ./$(TESTBIN); \
    42		  fi
    43	
    44	## soakcheck: 1-hour miniature of the graded 48h soak
    45	soakcheck:
    46		@echo "make soakcheck: not implemented yet - needs the supervisor and heartbeat logging."
    47		@echo "Per spec 3.4 this must exercise: startup, hourly heartbeat (liveness/RSS/event counts),"
    48		@echo "an injected fault with detect-degrade-recover, and an orderly shutdown."
    49	
    50	## deploy: rsync the tree to the Pi. usage: make deploy PI=pi@hostname
    51	deploy:
    52		@if [ -z "$(PI)" ]; then \
    53		    echo "usage: make deploy PI=pi@hostname"; exit 1; \
    54		  else \
    55		    rsync -av --exclude '.git' --exclude 'build' --exclude 'transcripts' ./ $(PI):~/term-project/; \
    56		  fi
    57	
    58	## clean: remove build artifacts
    59	clean:
    60		rm -rf build
    61	
    62	## help: list targets
    63	help:
    64		@grep -E '^## ' $(MAKEFILE_LIST) | sed 's/^## /  /'
    65	
    66	.PHONY: all test asan memcheck soakcheck deploy clean help
