     2	#define DSM_CRC32_H
     3	
     4	#include <stddef.h>
     5	#include <stdint.h>
     6	
     7	/* The standard CRC-32 (the one zlib, Ethernet and PNG use), so the output
     8	 * can be checked against published values. */
     9	uint32_t dsm_crc32(const void *data, size_t len);
