=================== src/common/crc32.c
     1	#include "common/crc32.h"
     2	
     3	/* Bit-at-a-time rather than the faster table version. We checksum about
     4	 * three 48-byte records a second, so speed doesn't matter, and this is the
     5	 * version that can be worked through by hand. */
     6	uint32_t dsm_crc32(const void *data, size_t len)
     7	{
     8	    const uint8_t *p = data;
     9	    uint32_t crc = 0xFFFFFFFFu;
    10	
    11	    for (size_t i = 0; i < len; i++) {
    12	        crc ^= p[i];
    13	        for (int bit = 0; bit < 8; bit++) {
    14	            if (crc & 1u)
    15	                crc = (crc >> 1) ^ 0xEDB88320u;
    16	            else
    17	                crc >>= 1;
    18	        }
    19	    }
    20	    return crc ^ 0xFFFFFFFFu;
    21	}
