     1	#ifndef DSM_RECORD_H
     2	#define DSM_RECORD_H
     3	
     4	#include <stdbool.h>
     5	#include <stddef.h>
     6	#include <stdint.h>
     7	
     8	#define DSM_SCHEMA_VER 1
     9	
    10	/* Starts at 1 so a zeroed record never looks like a real kind. */
    11	enum dsm_kind {
    12	    DSM_KIND_SAMPLE    = 1,
    13	    DSM_KIND_FEATURE   = 2,
    14	    DSM_KIND_STATE     = 3,
    15	    DSM_KIND_HEARTBEAT = 4,
    16	    DSM_KIND_FAULT     = 5,
    17	};
    18	
    19	/* Bits in dsm_record.flags. They describe the reading, not the bytes.
    20	 * SYNTHETIC is required by the spec: replayed or made-up data has to be
    21	 * labeled everywhere it appears, so it is part of the record itself. */
    22	enum dsm_flag {
    23	    DSM_FLAG_VALID       = 1u << 0,
    24	    DSM_FLAG_STALE       = 1u << 1,
    25	    DSM_FLAG_SYNTHETIC   = 1u << 2,
    26	    DSM_FLAG_CALIBRATING = 1u << 3,
    27	};
    28	
    29	/* One record, exactly as it sits on disk. */
    30	struct dsm_record {
    31	    uint64_t t_mono_ns;   /* CLOCK_MONOTONIC: for measuring intervals */
    32	    uint64_t t_real_ns;   /* CLOCK_REALTIME: the wall-clock label */
    33	    uint16_t schema_ver;
    34	    uint16_t source_id;   /* which process produced it */
    35	    uint16_t kind;        /* enum dsm_kind */
    36	    uint16_t flags;       /* enum dsm_flag bits */
    37	    int32_t  v[4];        /* fixed-point values; meaning depends on kind */
    38	    uint32_t seq;         /* per-source counter: a gap means lost data */
    39	    uint32_t crc32;       /* covers every byte before this field */
    40	};
    41	
    42	/* We write the struct's bytes straight to disk, so its layout IS the file
    43	 * format. If an edit changes the layout, the build stops here instead of
    44	 * the files quietly becoming unreadable. */
    45	_Static_assert(sizeof(struct dsm_record) == 48,
    46	               "dsm_record must be exactly 48 bytes");
    47	_Static_assert(offsetof(struct dsm_record, crc32) == 44,
    48	               "crc32 must be the last 4 bytes of the record");
    49	_Static_assert(__BYTE_ORDER__ == __ORDER_LITTLE_ENDIAN__,
    50	               "the on-disk format assumes a little-endian host");
    51	
    52	void record_init(struct dsm_record *r, enum dsm_kind kind, uint16_t source_id);
    53	void record_seal(struct dsm_record *r);
    54	bool record_intact(const struct dsm_record *r);
    55	
    56	#endif
