     1	#include "common/record.h"
     2	#include "common/crc32.h"
     3	
     4	#include <string.h>
     5	
     6	/* Zero the whole record first. Any byte left uninitialized would end up in
     7	 * the CRC, and valgrind on the Pi reports that as a use of uninitialized
     8	 * memory even when the result looks fine. */
     9	void record_init(struct dsm_record *r, enum dsm_kind kind, uint16_t source_id)
    10	{
    11	    memset(r, 0, sizeof *r);
    12	    r->schema_ver = DSM_SCHEMA_VER;
    13	    r->kind = (uint16_t)kind;
    14	    r->source_id = source_id;
    15	}
    16	
    17	void record_seal(struct dsm_record *r)
    18	{
    19	    r->crc32 = dsm_crc32(r, offsetof(struct dsm_record, crc32));
    20	}
    21	
    22	bool record_intact(const struct dsm_record *r)
    23	{
    24	    return r->crc32 == dsm_crc32(r, offsetof(struct dsm_record, crc32));
    25	}
