     9	/* A store file is one header followed by records, back to back:
    10	 *
    11	 *   [ header: 24 bytes ][ record 0: 48 ][ record 1: 48 ] ...
    12	 *
    13	 * Records are only ever added at the end. Nothing is rewritten in place.
    14	 *
    15	 * Durability today: store_append() hands the bytes to the kernel. It does
    16	 * not wait for them to reach the SD card (no fsync), so a power cut can
    17	 * still lose the most recent records. */
    18	
    19	#define DSM_STORE_MAGIC "DSKY"
    20	
    21	/* The first 24 bytes of every store file. */
    22	struct dsm_store_header {
    23	    char     magic[4];         /* "DSKY", no terminating zero */
    24	    uint16_t schema_ver;       /* DSM_SCHEMA_VER of the records inside */
    25	    uint16_t record_size;      /* sizeof(struct dsm_record) */
    26	    uint64_t created_real_ns;  /* CLOCK_REALTIME when the file was made */
    27	    uint32_t reserved;         /* always 0; puts crc32 last with no padding */
    28	    uint32_t crc32;            /* covers every byte before this field */
    29	};
    30	
    31	_Static_assert(sizeof(struct dsm_store_header) == 24,
    32	               "dsm_store_header must be exactly 24 bytes");
    33	_Static_assert(offsetof(struct dsm_store_header, crc32) == 20,
    34	               "crc32 must be the last 4 bytes of the header");
    35	
    36	enum store_status {
    37	    STORE_OK = 0,
    38	    STORE_ERR_IO,      /* a system call failed; errno says why */
    39	    STORE_ERR_FORMAT,  /* the file exists but is not a store file; untouched */
    40	    STORE_ERR_BADREC,  /* the record's CRC does not match; nothing written */
    41	    STORE_ERR_BROKEN,  /* an earlier write failed; no more appends */
    42	};
    43	
    44	/* Opaque: only store.c can see inside. */
    45	struct dsm_store;
    46	
    47	enum store_status store_open(const char *path, struct dsm_store **out);
    48	enum store_status store_append(struct dsm_store *s, const struct dsm_record *r);
    49	enum store_status store_close(struct dsm_store *s);
