     7	/* Fill with 0xAA first, so record_init has to actually overwrite garbage. */
     8	static void fresh(struct dsm_record *r)
     9	{
    10	    memset(r, 0xAA, sizeof *r);
    11	    record_init(r, DSM_KIND_SAMPLE, 7);
    12	}
    13	
    14	static void test_init(void)
    15	{
    16	    struct dsm_record r;
    17	    fresh(&r);
    18	    CHECK(r.schema_ver == DSM_SCHEMA_VER, "schema_ver %u, want %d",
    19	          r.schema_ver, DSM_SCHEMA_VER);
    20	    CHECK(r.kind == DSM_KIND_SAMPLE, "kind %u, want %d", r.kind, DSM_KIND_SAMPLE);
    21	    CHECK(r.source_id == 7, "source_id %u, want 7", r.source_id);
    22	    CHECK(r.flags == 0 && r.seq == 0 && r.crc32 == 0,
    23	          "flags/seq/crc32 not zeroed: %u %u %u", r.flags, r.seq, r.crc32);
    24	    CHECK(r.v[0] == 0 && r.v[1] == 0 && r.v[2] == 0 && r.v[3] == 0,
    25	          "v[] not zeroed");
    26	}
    27	
    28	static void test_sealed_is_intact(void)
    29	{
    30	    struct dsm_record r;
    31	    fresh(&r);
    32	    r.v[0] = 12345;
    33	    r.seq = 42;
    34	    record_seal(&r);
    35	    CHECK(record_intact(&r), "a freshly sealed record is not intact");
    36	}
    37	
    38	/* The core property: damage to ANY byte is caught, including the four
    39	 * bytes of the CRC itself. CRC-32 is guaranteed to catch any damage that
    40	 * fits inside 32 bits in a row, so one bad byte is always caught. */
    41	static void test_every_byte_flip_is_caught(void)
    42	{
    43	    struct dsm_record r;
    44	    fresh(&r);
    45	    r.t_real_ns = 1761436800000000000ull;
    46	    r.v[2] = -900;
    47	    record_seal(&r);
    48	
    49	    unsigned char *bytes = (unsigned char *)&r;
    50	    int missed = 0;
    51	    for (size_t i = 0; i < sizeof r; i++) {
    52	        bytes[i] ^= 0xFF;
    53	        if (record_intact(&r))
    54	            missed++;
    55	        bytes[i] ^= 0xFF;
    56	    }
    57	    CHECK(missed == 0, "%d of %zu byte flips went undetected", missed, sizeof r);
    58	    CHECK(record_intact(&r), "record not intact after undoing every flip");
    59	}
    60	
    61	/* A power cut can leave a stretch of zeros at the end of a file. That
    62	 * must never be read back as a real record. */
    63	static void test_all_zeros_is_not_intact(void)
    64	{
    65	    struct dsm_record r;
    66	    memset(&r, 0, sizeof r);
    67	    CHECK(!record_intact(&r), "an all-zero record passed as intact");
    68	}
