    70	/* Seal last. Editing any field afterward breaks the record until resealed. */
    71	static void test_edit_after_seal(void)
    72	{
    73	    struct dsm_record r;
    74	    fresh(&r);
    75	    record_seal(&r);
    76	    r.seq = 99;
    77	    CHECK(!record_intact(&r), "editing seq after sealing went undetected");
    78	    record_seal(&r);
    79	    CHECK(record_intact(&r), "resealing did not make it intact again");
    80	}
