    16	    got = dsm_crc32(fox, strlen(fox));
    17	    CHECK(got == 0x414FA339u, "fox: got %08x, want 414fa339", got);
    18	
    19	    got = dsm_crc32("", 0);
    20	    CHECK(got == 0x00000000u, "empty input: got %08x, want 00000000", got);
    21	
    22	    /* This is the property the storage layer relies on: a record that
    23	     * picked up any single wrong bit must not still pass its CRC. */
    24	    unsigned char msg[9];
    25	    memcpy(msg, "123456789", sizeof msg);
    26	    uint32_t clean = dsm_crc32(msg, sizeof msg);
    27	    int missed = 0;
    28	    for (size_t bit = 0; bit < 8 * sizeof msg; bit++) {
    29	        msg[bit / 8] ^= (unsigned char)(1u << (bit % 8));
    30	        if (dsm_crc32(msg, sizeof msg) == clean)
    31	            missed++;
    32	        msg[bit / 8] ^= (unsigned char)(1u << (bit % 8));
    33	    }
