   164	
   165	    unsigned char back[HDR + MAX_RECS * REC];
   166	    size_t n = read_raw(back, sizeof back);
   167	    CHECK(n == len && memcmp(back, bytes, len) == 0, "%s: file was modified", what);
   168	}
   169	
   170	static void test_foreign_files_refused(void)
   171	{
   172	    const char text[] = "somebody's notes file, definitely not ours\n";
   173	    check_refused(text, sizeof text - 1, "text file");
   174	
   175	    const char shorty[] = "DSKY123456";
   176	    check_refused(shorty, sizeof shorty - 1, "file shorter than a header");
   177	
   178	    /* A real store file with one byte of its header damaged. */
   179	    unlink(path);
   180	    struct dsm_store *s = NULL;
   181	    if (store_open(path, &s) != STORE_OK) {
   182	        CHECK(0, "open failed");
   183	        return;
   184	    }
   185	    append_range(s, 0, 2);
   186	    store_close(s);
   187	    unsigned char buf[HDR + 2 * REC];
   188	    size_t n = read_raw(buf, sizeof buf);
   189	    CHECK(n == sizeof buf, "store file is %zu bytes, want %zu", n, sizeof buf);
   190	    buf[10] ^= 0xFF;   /* inside created_real_ns */
   191	    check_refused(buf, n, "damaged header");
   192	}
   193	
   194	/* A header that matches what store_open() writes, with its CRC sealed. */
   195	static void good_header(struct dsm_store_header *h)
   196	{
   197	    memset(h, 0, sizeof *h);
   198	    memcpy(h->magic, DSM_STORE_MAGIC, sizeof h->magic);
   199	    h->schema_ver = DSM_SCHEMA_VER;
   200	    h->record_size = REC;
   201	    h->created_real_ns = 1761436800000000000ull;
   202	    h->crc32 = dsm_crc32(h, offsetof(struct dsm_store_header, crc32));
   203	}
   204	
   205	/* The CRC only proves the header wasn't damaged. A header can be intact
   206	 * and still wrong for us: a different kind of file, or one written by a
   207	 * newer version with a different record format. Each field is checked. */
   208	static void test_intact_but_wrong_header_refused(void)
   209	{
   210	    const size_t crc_at = offsetof(struct dsm_store_header, crc32);
   211	    struct dsm_store_header h;
   212	
   213	    good_header(&h);
   214	    write_raw(&h, sizeof h);
   215	    struct dsm_store *s = NULL;
   216	    CHECK(store_open(path, &s) == STORE_OK, "a correct header was refused");
   217	    store_close(s);
   218	
   219	    good_header(&h);
   220	    h.magic[3] = 'X';
   221	    h.crc32 = dsm_crc32(&h, crc_at);
   222	    check_refused(&h, sizeof h, "different magic");
   223	
   224	    good_header(&h);
   225	    h.schema_ver = DSM_SCHEMA_VER + 1;
   226	    h.crc32 = dsm_crc32(&h, crc_at);
   227	    check_refused(&h, sizeof h, "newer schema version");
   228	
   229	    good_header(&h);
   230	    h.record_size = REC + 16;
   231	    h.crc32 = dsm_crc32(&h, crc_at);
   232	    check_refused(&h, sizeof h, "different record size");
   233	}
   234	
   235	/* A record whose CRC doesn't match must never reach the file. Later,
   236	 * recovery cuts the file off at the first bad record, so one bad record
   237	 * written now would throw away every good record written after it. */
   238	static void test_bad_record_refused(void)
   239	{
   240	    unlink(path);
   241	    struct dsm_store *s = NULL;
   242	    if (store_open(path, &s) != STORE_OK) {
   243	        CHECK(0, "open failed");
   244	        return;
   245	    }
   246	    struct dsm_record r = make_rec(0);
   247	    r.v[1] = 5;   /* changed after sealing */
   248	    CHECK(store_append(s, &r) == STORE_ERR_BADREC, "unsealed record accepted");
   249	    store_close(s);
   250	    CHECK(file_size() == HDR, "file is %ld bytes; the bad record got in", file_size());
   251	}
   252	
   253	/* Make a write really fail: lower the largest file size this process is
   254	 * allowed to write (RLIMIT_FSIZE) so the third record doesn't fit. After
   255	 * that, we don't know where the file ends, so every later append must be
   256	 * refused, even once the limit is lifted again. */
   257	static void test_failed_write_stops_appends(void)
   258	{
   259	    unlink(path);
   260	    struct dsm_store *s = NULL;
   261	    if (store_open(path, &s) != STORE_OK) {
   262	        CHECK(0, "open failed");
   263	        return;
   264	    }
   265	
   266	    struct rlimit old, low;
   267	    if (getrlimit(RLIMIT_FSIZE, &old) != 0) {
   268	        CHECK(0, "getrlimit failed");
   269	        store_close(s);
   270	        return;
   271	    }
   272	    low = old;
   273	    low.rlim_cur = HDR + 2 * REC + 10;   /* room for two records and 10 bytes */
   274	
   275	    /* Without this, going over the limit kills the process with SIGXFSZ
   276	     * instead of returning an error from write(). */
   277	    void (*old_handler)(int) = signal(SIGXFSZ, SIG_IGN);
   278	    int lowered = setrlimit(RLIMIT_FSIZE, &low) == 0;
   279	
   280	    struct dsm_record r0 = make_rec(0), r1 = make_rec(1), r2 = make_rec(2);
   281	    enum store_status a = store_append(s, &r0);
   282	    enum store_status b = store_append(s, &r1);
   283	    enum store_status c = store_append(s, &r2);
   284	
   285	    setrlimit(RLIMIT_FSIZE, &old);
   286	    signal(SIGXFSZ, old_handler);
   287	
   288	    struct dsm_record r3 = make_rec(3);
   289	    enum store_status d = store_append(s, &r3);
   290	    store_close(s);
   291	
   292	    CHECK(lowered, "setrlimit failed, so this test proved nothing");
   293	    CHECK(a == STORE_OK && b == STORE_OK, "appends under the limit failed: %d %d", a, b);
   294	    CHECK(c == STORE_ERR_IO, "append over the limit returned %d, want STORE_ERR_IO", c);
   295	    CHECK(d == STORE_ERR_BROKEN, "append after a failure returned %d, want STORE_ERR_BROKEN", d);
   296	    long size = file_size();
   297	    CHECK(size >= HDR + 2 * REC && size <= HDR + 2 * REC + 10,
   298	          "file is %ld bytes, want %d..%d", size, HDR + 2 * REC, HDR + 2 * REC + 10);
   299	}
   300	
   301	void test_store(void)
   302	{
   303	    /* Not mkdtemp(): macOS hides it under -D_POSIX_C_SOURCE. The process
   304	     * ID makes the name unique for as long as this test runs. */
   305	    const char *tmp = getenv("TMPDIR");
   306	    snprintf(dir, sizeof dir, "%s/dsm-test-%ld",
   307	             tmp != NULL && *tmp ? tmp : "/tmp", (long)getpid());
   308	    if (mkdir(dir, 0700) != 0 && errno != EEXIST) {
   309	        CHECK(0, "mkdir(%s) failed", dir);
   310	        return;
   311	    }
   312	    snprintf(path, sizeof path, "%s/store.dsm", dir);
   313	
   314	    test_new_file_gets_header();
   315	    test_append_and_read_back();
   316	    test_reopen_appends_at_end();
   317	    test_foreign_files_refused();
   318	    test_intact_but_wrong_header_refused();
   319	    test_bad_record_refused();
   320	    test_failed_write_stops_appends();
   321	
   322	    unlink(path);
   323	    rmdir(dir);
   324	}

